const destinations=[['overview','Investment Overview','◈','overview.html#overview'],['portfolio','Portfolio Manager','▣','overview.html#portfolio'],['screener','Opportunity Screener','⌕','research.html#screener'],['stock','Stock Research','▤','research.html#stock'],['decision','Decision Workspace','◇','research.html#decision'],['planner','Trade Planner','▦','research.html#planner'],['performance','Performance & Strategy','↗','overview.html#performance'],['health','Data Health','◉','overview.html#health']];
const nav=document.querySelector('.navitems');
nav.innerHTML=destinations.map(([id,label,icon,href],i)=>`${i===0?'<div class="navgroup">INVESTMENT MANAGEMENT</div>':''}${i===6?'<div class="navgroup">EVALUATE & VERIFY</div>':''}<a class="navlink" data-destination="${id}" href="${href}"><span class="icon" aria-hidden="true">${icon}</span>${label}</a>`).join('');
function activate(){const fallback=document.body.dataset.default;const id=location.hash.slice(1)||fallback;const target=document.getElementById(id);if(!target||!target.classList.contains('view'))return;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('.navlink').forEach(a=>{const on=a.dataset.destination===id;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const title=target.dataset.title||id;document.querySelector('.breadcrumbs strong').textContent=title;document.title=`${title} · BVMT M14 design prototype`;window.scrollTo(0,0)}
window.addEventListener('hashchange',activate);activate();
const toast=document.querySelector('.toast');let timer;function notify(message){toast.textContent=message;toast.classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('visible'),4000)}
document.querySelectorAll('[data-toast]').forEach(b=>b.addEventListener('click',()=>notify(b.dataset.toast)));
document.querySelectorAll('[data-open-dialog]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.openDialog).showModal()));
document.querySelectorAll('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
document.querySelectorAll('.segmented button').forEach(b=>b.addEventListener('click',()=>{b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');const chart=document.querySelector('.chartline');if(chart&&b.dataset.path)chart.setAttribute('d',b.dataset.path);const label=document.querySelector('[data-chart-period]');if(label)label.textContent=b.textContent.trim()+' synthetic sessions';document.querySelectorAll('[data-axis-period]').forEach(e=>e.textContent=b.textContent.trim()==='90D'?e.dataset.axis90:e.dataset.axis30);}));
const query=document.getElementById('stock-search');const coverage=document.getElementById('coverage-filter');function filterRows(){if(!query)return;const q=query.value.toLowerCase().trim();let count=0;document.querySelectorAll('[data-stock-row]').forEach(r=>{const shown=r.textContent.toLowerCase().includes(q)&&(!coverage.value||r.dataset.coverage===coverage.value);r.classList.toggle('noshow',!shown);if(shown)count++});document.getElementById('result-count').textContent=`${count} synthetic securities`;document.getElementById('no-results').classList.toggle('noshow',count>0)}if(query){query.addEventListener('input',filterRows);coverage.addEventListener('change',filterRows)}
document.querySelectorAll('[data-evidence-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-evidence-tab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-evidence-panel]').forEach(p=>p.classList.toggle('noshow',p.dataset.evidencePanel!==b.dataset.evidenceTab))}));
const scenario=document.getElementById('evidence-scenario');if(scenario)scenario.addEventListener('change',()=>{const text={sparse:['Partial evidence','Historical observations have gaps. Publication times remain unknown.'],stale:['Stale market evidence','The fixture EOD observation is outside the selected decision cutoff.'],empty:['Insufficient evidence','No source observations are available. No price or strength score is inferred.']}[scenario.value];document.querySelectorAll('[data-scenario-title]').forEach(e=>e.textContent=text[0]);document.querySelectorAll('[data-scenario-description]').forEach(e=>e.textContent=text[1]);document.querySelectorAll('[data-quote]').forEach(e=>e.textContent=scenario.value==='empty'?'Unavailable':'14.600 TND · synthetic EOD');const line=document.getElementById('research-chart-line');if(line)line.style.visibility=scenario.value==='empty'?'hidden':'visible';const noChart=document.getElementById('chart-no-data');if(noChart)noChart.style.display=scenario.value==='empty'?'block':'none';notify('Evidence scenario changed. Trading remains blocked.');});
const note=document.getElementById('research-note');const save=document.getElementById('save-note');if(save)save.addEventListener('click',()=>{document.getElementById('note-status').textContent=note.value.trim()?'Draft note kept in this page only. Reload clears it.':'Write a research question before saving a draft.';notify(note.value.trim()?'Draft saved in page memory only. No account was changed.':'Add a note before saving.')});
const calc=document.getElementById('review-calculation');if(calc)calc.addEventListener('click',()=>{const limit=document.getElementById('limit-input').value;document.getElementById('limit-output').textContent=limit&&Number(limit)>0?`${Number(limit).toFixed(3)} TND · user input`:'Unavailable · no valid limit entered';notify('Illustration updated. Quantity remains zero until evidence gates pass.');});
